function unitStateLabel(u){if(u.stance==='alert')return '警戒待命 · 发现附近敌军时唤醒';if(u.moveOrder)return '连续行军 · 目的地 '+u.moveOrder.destination;if(u.activity?.action.type==='upgrade')return `装备整备 · ${fmt(Math.max(0,u.activity.ends-(session.time||0)))} 秒`;if(u.receivingTreatment)return '接受治疗中 · 请停留';if(u.activity?.action.type==='heal')return `施术中 · ${fmt(Math.max(0,u.activity.ends-(session.time||0)))} 秒`;if(UNITS[u.type].medical)return `医疗支援 · ${(u.supportUntil||0)>(session.time||0)?'治疗冷却 '+Math.ceil(u.supportUntil-session.time)+' 秒':'治疗就绪'}`;if(u.activity?.action.type==='trainVeteran')return `${VETERAN_TRAITS[u.activity.action.item]?.name||'专长训练'} · ${fmt(Math.max(0,u.activity.ends-(session.time||0)))} 秒`;if(UNITS[u.type].domain==='air')return u.activity?.action.type==='rebase'?'飞往新机场':u.airPatrolCity!==undefined?'城市上空巡逻':UNITS[u.type].consumable?'一次性攻击 · 投弹后自爆':'机场驻扎 · 空中任务';if(u.type==='envoy')return u.envoy?.protected?'金光保护 · 前往首都':'保护结束 · 谈判来使';return u.transport==='cargo'?'重型运输船':u.transport==='wood'?'小木船运输':UNITS[u.type].domain==='sea'?'海军舰艇':'陆地行军';}
