async function unitCommand(u,type,item){
  if(type==='move'&&UNITS[u.type].domain==='air')type='rebase';
  const targeted=['jump','nuke','patrol','move','separate','linkUnits','rebase','attack','attackCityState','spread','heal'].includes(type),request=targeted?++orderRequest:orderRequest,world=game.id,owner=selectedPlayer;
  try{const obs=await api('observation?player='+owner+(['move','separate'].includes(type)?'&unit='+u.id:''));if(targeted&&request!==orderRequest||game.id!==world||selectedPlayer!==owner||selection?.id!==u.id)return;const current=game.units.find(v=>v.id===u.id);if(targeted&&(!current||current.acted||current.tile!==u.tile))return;const combined=type==='move'&&session.mode==='turns',actions=obs.legalActions.filter(a=>a.unit===u.id&&(combined?['move','attack','attackCityState'].includes(a.type):type==='attack'?['attack','attackCityState'].includes(a.type):a.type===type)&&(!item||a.item===item));if(!actions.length&&!(combined&&current?.moves>0)){toast({found:'城市之间需要至少四格距离，且不能在水面或山脉建城。',improve:'此地块不可改良，或所需科技尚未解锁。',chop:'砍伐需要对应科技、剩余建造次数，以及三格内的己方城市。',attack:'射程内没有已宣战的目标。',upgrade:'尚无可用升级，或金币、战略资源不足。',spread:'附近没有可传播的城市。',heal:'附近没有空闲的己方陆军伤员，或治疗间隔尚未结束。'}[type]||'当前没有可用目标。');return;}
    if(targeted){
      const mapped=actions.map(a=>({...a,tile:a.tile??game.units.find(u=>u.id===a.targetUnit)?.tile??game.cities.find(c=>c.id===a.targetCity)?.tile??game.cityStates?.states.find(s=>s.id===a.state)?.tile,command:a}));orderMode={actions:mapped,label:type,unit:u.id,from:u.tile};renderer.orders=mapped;renderer.dirty=true;$('map').classList.add('order-mode');$('order-hint').hidden=false;$('order-hint').textContent=type==='nuke'?'选择核打击目标 · 悬停查看 5×5 受损范围和己方损失 · Esc 取消':type==='patrol'?'选择长期巡逻保护的城市 · Esc 取消':type==='linkUnits'?'点击相邻己方支援 / 陆军建立两人编队 · Esc 取消':type==='separate'?'点击空地分离移动 · Esc 取消':type==='heal'?'点击高亮伤员进行治疗 · Esc 取消':type==='rebase'?'点击高亮机场或航母转场 · Esc 取消':type==='jump'?'选择高亮落点跳跃 · 消耗 2 移动力 · Esc 取消':type==='move'?(session.mode==='turns'?'点击地块移动 · 红色目标可攻击 · 远处预设行军 · Esc 取消':'点击高亮地块移动 · Esc 取消'):type==='attack'?'点击高亮目标攻击 · Esc 取消':'点击高亮城市传播信条 · Esc 取消';if(session.mode==='turns')$('order-hint').textContent=$('order-hint').textContent.replaceAll('点击','右键').replace('Esc 取消','左键 / Esc 取消');orderMode.prompt=$('order-hint').textContent;
    }else {const action={...actions[0]};if(type==='upgrade')action.expectedCost=u.upgradeOptions?.find(op=>op.item===item)?.goldCost??action.hint.goldCost;delete action.hint;act(action);}
  }catch(e){toast(e.message,true);}
}
