function renderImperial(){const p=currentPlayer(),options={control:canControl(p.id),act,redraw:renderImperial,openLeader,focus:tile=>{closeModal();renderer.focus(tile);},peace:id=>{closeModal();audience.openCompose(p.id,id);}};if(activeModal==='audience')mountCourt($('modal-body'),game,p,{...options,target:courtTarget});if(activeModal==='governors')mountGovernors($('modal-body'),game,p,options);if(activeModal==='worldsystems')mountWorldSystems($('modal-body'),game,p,options);}
async function openModal(name){
  if(name==='climate'){const opener=document.querySelector('[data-b-menu]')||document.activeElement;closeModal();cancelOrder();climatePanel.open(opener);return;}
  climatePanel.close();
  if(name!=='audio')audio.stopPreview();
  // Let the active presentation own a page regardless of which task or shortcut opened it.
  cancelOrder();
  if(!document.dispatchEvent(new CustomEvent('hex:open-panel',{cancelable:true,detail:{name}})))return;
  delete $('modal').dataset.workshop;
  activeModal=name;$('modal').dataset.page=name;$('modal').scrollTop=0;$('modal').classList.toggle('research-modal',['tech','civic'].includes(name));if(name==='diplomacy')modalTab='relations';
  if(['setup','drivers','saves','round'].includes(name)&&session?.running)await api('pause');
  $('modal-title').textContent={modelApi:'API 玩家设置',audience:'外交会晤',governors:'行省总督',worldsystems:'诸国档案',setup:'新的文明纪元',leaders:'领袖与国家战略',wonders:'世界奇观',greatpeople:'伟人名录',religion:'信仰议会',tech:'科技树',civic:'市政与政策',age:'时代加成',congress:'国际大会',diplomacy:'世界议会',drivers:'C++ 玩家驱动',saves:'保存世界',help:'文明的第一步',victory:'历史铭记此刻'}[name]||'';
  if(name==='round')$('modal-title').textContent='经济结算报告';
  $('modal-kicker').textContent={audience:'PACTA ET LEGATIONES',governors:'MAGISTRATUS IMPERII',worldsystems:'ORBIS ET HOMINES',setup:'A WORLD WAITING TO BE WRITTEN',wonders:'MONUMENTA MUNDI',greatpeople:'VITAE ILLUSTRIUM',religion:'FIDE ET HISTORIA',tech:'THE PURSUIT OF KNOWLEDGE',age:'AN AGE DEDICATED',civic:'THE SHAPE OF SOCIETY',diplomacy:'THE WORLD COUNCIL',drivers:'EIGHT MINDS. ONE WORLD.',saves:'THE ARCHIVE OF HISTORY',help:'THE FIRST HORIZON',victory:'AN AGE REMEMBERED'}[name]||'THE COUNCIL';
  $('modal-body').innerHTML='<div class="modal-busy">正在载入议会档案…</div>';if(!$('modal').open)$('modal').showModal();
  try{if(name==='setup'||name==='drivers')drivers=(await api('drivers')).drivers;await renderModal();}catch(e){$('modal-body').innerHTML=`<p class="driver-error">${esc(e.message)}</p>`;}
}
