async function renderModal(){
  if(activeModal==='modelApi'){await renderModelApi();return;}
  if(activeModal==='cityWorkshop'){renderCityWorkshop();return;}

  if(['audience','governors','worldsystems'].includes(activeModal)){renderImperial();return;}
  if(activeModal==='religion')await mountReligionCouncil($('modal-body'),game,currentPlayer(),{control:canControl(selectedPlayer),loadActions:async()=>(await api('observation?player='+selectedPlayer)).legalActions,act});else if(activeModal==='wonders')mountHeritage($('modal-body'),game,currentPlayer(),{kind:activeModal,act,loadActions:async()=>(await api('observation?player='+selectedPlayer)).legalActions,focus:tile=>{closeModal();renderer.focus(tile);}});else if(activeModal==='audio')renderAudio();else if(activeModal==='leaders')renderLeaders();else if(activeModal==='setup')renderSetup();else if(activeModal==='congress')renderCongress();else if(activeModal==='diplomacy')renderDiplomacy();else if(activeModal==='drivers')renderDrivers();else if(activeModal==='saves')await renderSaves();else if(activeModal==='help')renderHelp();else if(activeModal==='victory')renderVictory();else if(activeModal==='round')renderRound();
}
