  async function prepareConnection(){const settings=collectSettings();const status=await api('lobby/prepare',settings);preparedDraft=draftFingerprint();lobbyStatus=status;syncMcpSeat();return status;}
  $('setup-details-close').onclick=()=>{$('setup-connection-details').hidden=true;$('setup-mcp-export').textContent='';$('setup-mcp-export').hidden=true;};
  function collectSettings(){
    remember();
    let count=Number($('setup-count').value);
    const slice=()=>draft.slice(0,count);
    if(slice().some(seat=>['agent','api'].includes(seat.controller))&&count<2){count=2;$('setup-count').value='2';}
    if($('setup-play-mode').value==='realtime'&&slice().some(seat=>['agent','api'].includes(seat.controller)))throw new Error('外部 AI 需要回合制。实时观战不能接入 MCP。');
    for(const seat of slice()){
      if(seat.controller!=='api')continue;
      const name=seat.aiName.trim();
      if(!name||[...name].length>24||/[\u0000-\u001f【】]/.test(name))throw new Error('外部 AI 需要 1 到 24 个字符的名称，且不能包含换行或中文方括号。');
    }
    const fixed=slice().filter(seat=>seat.leader!=='random').map(seat=>seat.leader);
    const pool=LEADERS.map(leader=>leader.key).filter(key=>!fixed.includes(key));
    const random=new Uint32Array(Math.max(1,pool.length));crypto.getRandomValues(random);
    for(let i=pool.length-1;i>0;i--){const j=Math.floor(random[i]/2**32*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
    for(let i=0;i<count;i++)if(draft[i].leader==='random')draft[i].leader=pool.pop();
    const leaders=selectLeaderKeys(count,slice().map(seat=>seat.leader));
    leaders.forEach((key,index)=>{draft[index].leader=key;});
    roster();
    const chosen=draft.slice(0,count);
    return {victories:[...document.querySelectorAll('[data-setup-victory]:checked')].map(node=>node.dataset.setupVictory),playMode:$('setup-play-mode').value,seed:$('setup-seed').value.trim(),players:count,mapType:$('setup-map').value,size:$('setup-size').value,maxTurns:Number($('setup-turns').value),gameSpeed:$('setup-game-speed').value,rainfall:$('setup-rainfall').value,resourceAbundance:$('setup-resources').value,naturalWondersEnabled:$('setup-natural-wonders').value==='on',climateEnabled:$('setup-disasters').value!=='off',disasterIntensity:$('setup-disasters').value==='off'?0:Number($('setup-disasters').value),barbarians:$('setup-barbarians').checked,wrapX:true,autosaveEnabled:$('setup-autosave').checked,autosaveEvery:Number($('setup-autosave-every').value),leaders,doctrines:chosen.map(seat=>seat.doctrine),strategies:chosen.map(seat=>seat.strategy),drivers:chosen.map(seat=>seat.driver),seats:chosen.map((seat,index)=>({seat:index,kind:seat.controller==='api'?'agent':seat.controller,...(['agent','api'].includes(seat.controller)?{displayName:seat.controller==='agent'?'待识别':seat.aiName.trim(),autoName:seat.controller==='agent',agentId:`seat-${index}`}:{})}))};
  }
