function collectUiControls(){
  const nodes=climatePanel.isOpen?[...climatePanel.element.querySelectorAll('button')]:[...document.querySelectorAll('#modal[open] button, #modal[open] [data-tree-item], #modal[open] [data-b4-item], #modal[open] [data-b4-research], #player-task-dock button, #start-menu button, #civ-rankings-btn, #civ-rankings.open button, #civ-rankings.open summary, [data-b-vic], [data-modal]')];
  const seen=new Set(),controls=[];
  for(const el of nodes){
    if(el.closest('#modal:is([data-page="setup"],[data-page="modelApi"]), #model-observer'))continue;
    if(controls.length>=200)break;
    const base=el.id||(el.dataset.treeItem&&`tree-${el.dataset.treeItem}`)||(el.dataset.b4Item&&`b4-${el.dataset.b4Item}`)||(el.hasAttribute('data-b4-research')?'b4-research':null)||(el.dataset.modal&&`open-${el.dataset.modal}`)||(el.dataset.setupTab&&`setup-tab-${el.dataset.setupTab}`)||`ctl-${(el.getAttribute('aria-label')||el.textContent||'item').trim().slice(0,40)}`;
    let id=base,n=2;while(seen.has(id))id=`${base}-${n++}`;seen.add(id);el.dataset.uiId=id;
    controls.push({id,label:(el.getAttribute('aria-label')||el.textContent||'').trim().slice(0,80),disabled:!!el.disabled});
  }
  return controls;
}
function installUiBridge(){
  if(window.__uiBridge)return;
  let pageInstance=sessionStorage.getItem('hex-civ-page');
  if(!pageInstance||!/^[A-Za-z0-9_-]{8,80}$/.test(pageInstance)){pageInstance=crypto.randomUUID();sessionStorage.setItem('hex-civ-page',pageInstance);}
  window.__uiBridge=setInterval(async()=>{
    try{
      const access=sessionStorage.getItem('hex-civ-access');
      if(!access)return;
      const response=await fetch('/api/ui-bridge',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+access},body:JSON.stringify({pageInstance,page:climatePanel.isOpen?'climate':$('modal')?.open?($('modal').dataset.page||null):null,controls:collectUiControls()})});
      const data=await response.json();
      if(!response.ok||!data?.ok)return;
      const id=data?.click?.id;if(!id)return;
      const target=document.querySelector(`[data-ui-id="${CSS.escape(id)}"]`);
      if(target&&!target.disabled&&!target.closest('#modal:is([data-page="setup"],[data-page="modelApi"]), #model-observer'))target.click();
    }catch{}
  },400);
}
